import json,glob,os
inp={d["id"]:d for d in json.load(open("inputs.json",encoding="utf-8"))}
tax=json.load(open("taxonomy.json",encoding="utf-8"))
for qid in ["Q73","Q74","Q75","Q76","Q77","Q78","Q79","Q80"]:
    p=f"drafts/{qid}.json"
    d=json.load(open(p,encoding="utf-8"))
    ok_src = d["sourceFile"]==inp[qid]["sourceFile"]
    issues=[]
    if not ok_src: issues.append("sourceFile mismatch: "+repr(inp[qid]["sourceFile"]))
    if d["primaryDomain"] not in d["domains"]: issues.append("primary not in domains")
    for k,f in [("domains","domains"),("audiences","audiences"),("sports","sports"),("populations","populations")]:
        for v in d[k]:
            if v not in tax[f]: issues.append(f"bad {k}: {v}")
    if d["primaryDomain"] not in tax["domains"]: issues.append("bad primary")
    if d["studyDesign"] not in tax["studyDesigns"]: issues.append("bad design")
    txt=json.dumps(d,ensure_ascii=False)
    if "—" in txt: issues.append("em dash")
    if "–" in txt: issues.append("en dash")
    print(qid, d["decision"], d["paper"]["year"], d["paper"]["doi"], "OK" if not issues else issues)
'

